import fastify from './fastify'
import * as http from 'node:http'
import * as https from 'node:https'
import * as http2 from 'node:http2'

type Eq<A, B> = (<T>() => T extends A ? 1 : 2) extends (<T>() => T extends B ? 1 : 2) ? true : false
const assert = <T extends true>(_x?: T) => { void _x }
type ServerOf<T> = T extends { server: infer S } ? S : never

// falsy http2 resolves to the plain http server
assert<Eq<ServerOf<typeof plainFalse>, http.Server>>()
const plainFalse = fastify({ http2: false })

const plainUndefined = fastify({ http2: undefined })
assert<Eq<ServerOf<typeof plainUndefined>, http.Server>>()

const plainDynamic = fastify({ http2: false as const, bodyLimit: 1024, trustProxy: true })
assert<Eq<ServerOf<typeof plainDynamic>, http.Server>>()

// falsy http2 alongside https resolves to the https server
const secureFalse = fastify({ http2: false, https: {} })
assert<Eq<ServerOf<typeof secureFalse>, https.Server>>()

// http2: true still resolves to the http2 servers
const h2 = fastify({ http2: true })
assert<Eq<ServerOf<typeof h2>, http2.Http2Server>>()

const h2secure = fastify({ http2: true, https: {} })
assert<Eq<ServerOf<typeof h2secure>, http2.Http2SecureServer>>()

// explicit http2 generics still reject a false literal
// @ts-expect-error  Type 'false' is not assignable to type 'true'.
fastify<http2.Http2Server>({ http2: false })
// @ts-expect-error  Type 'false' is not assignable to type 'true'.
fastify<http2.Http2SecureServer>({ http2: false })

