const ts = require('typescript')
const path = require('node:path')

const files = process.argv.slice(2)
const program = ts.createProgram(files, {
  strict: true,
  noEmit: true,
  target: ts.ScriptTarget.ES2022,
  module: ts.ModuleKind.CommonJS,
  moduleResolution: ts.ModuleResolutionKind.Node10,
  esModuleInterop: true,
  skipLibCheck: true,
  types: ['node']
})
const diagnostics = ts.getPreEmitDiagnostics(program).filter(d => {
  const f = d.file && d.file.fileName
  return !f || files.some(n => f.endsWith(path.basename(n)))
})
for (const d of diagnostics) {
  const msg = ts.flattenDiagnosticMessageText(d.messageText, ' ')
  const where = d.file ? `${path.basename(d.file.fileName)}:${d.file.getLineAndCharacterOfPosition(d.start).line + 1}` : '-'
  console.log(`${where} TS${d.code}: ${msg}`)
}
console.log(`${diagnostics.length} error(s) in target files`)

